559	    /**
560	     * Return the Pet with the given name, or null if none found for this Owner.
561	     *
562	     * @param name to test
563	     * @return true if pet name is already in use
564	     */
565	    public Pet getPet(String name, boolean ignoreNew) {
566	        name = name.toLowerCase();
567	        for (Pet pet : getPetsInternal()) {
568	            if (!ignoreNew || !pet.isNew()) {
569	                String compName = pet.getName();
570	                compName = compName.toLowerCase();
571	                if (compName.equals(name)) {
572	                    return pet;
573	                }
574	            }
575	        }
576	        return null;
577	    }
