699	/**
700	 * Global Exception handler for REST controllers.
701	 * <p>
702	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
703	 *
704	 * @author Vitaliy Fedoriv
705	 * @author Alexander Dudkin
706	 */
707	@ControllerAdvice
708	public class ExceptionControllerAdvice {
709	
710	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
711	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
712	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
713	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
714	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
715	    private static final String ERROR_INVALID_EMAIL = "The request contains an invalid email address";
716	
717	    /**
718	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
719	     * class.
720	     *
721	     * @param e     Object referring to the thrown exception.
722	     * @param status HTTP response status.
723	     * @param url URL request.
724	     */
725	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
726	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
727	        problemDetail.setType(URI.create(url.toString()));
728	        problemDetail.setTitle(e.getClass().getSimpleName());
729	        problemDetail.setDetail(detail);
730	        problemDetail.setProperty("timestamp", Instant.now());
731	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
732	        return problemDetail;
733	    }
734	
735	    /**
736	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
737	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
738	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
739	     * would catch it and report an authorization failure as a 500.
740	     *
741	     * @param e The {@link AccessDeniedException} to propagate
742	     * @throws AccessDeniedException always
743	     */
744	    @ExceptionHandler(AccessDeniedException.class)
745	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
746	        throw e;
747	    }
748	
749	    /**
750	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
751	     *
752	     * @param e The {@link Exception} to be handled
753	     * @param request {@link HttpServletRequest} object referring to the current request.
754	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
755	     */
756	    @ExceptionHandler(Exception.class)
757	    @ResponseBody
758	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
759	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
760	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
761	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
762	        return ResponseEntity.status(status).body(detail);
763	    }
764	
765	    /**
766	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
767	     * method returns a 404 Not Found status if an entity does not exist.
768	     *
769	     * @param e The {@link DataIntegrityViolationException} to be handled
770	     * @param request {@link HttpServletRequest} object referring to the current request.
771	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
772	     */
773	    @ExceptionHandler(DataIntegrityViolationException.class)
774	    @ResponseBody
775	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
776	        logger.warn("Data integrity violation at {} {}: {}",
777	            request.getMethod(),
778	            request.getRequestURI(),
779	            e.getMessage());
780	        logger.debug("Data integrity violation stacktrace", e);
781	        HttpStatus status = HttpStatus.NOT_FOUND;
782	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
783	        return ResponseEntity.status(status).body(detail);
784	    }
785	
786	    /**
787	     * Handles exception thrown by Bean Validation on controller methods parameters
788	     *
789	     * @param e The {@link MethodArgumentNotValidException} to be handled
790	     * @param request {@link HttpServletRequest} object referring to the current request.
791	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
792	     */
793	    @ExceptionHandler(MethodArgumentNotValidException.class)
794	    @ResponseBody
795	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
796	        HttpStatus status = HttpStatus.BAD_REQUEST;
797	        BindingErrorsResponse errors = new BindingErrorsResponse();
798	        BindingResult bindingResult = e.getBindingResult();
799	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
800	        List<String> invalidFields = bindingResult.getFieldErrors().stream()
801	            .map(FieldError::getField)
802	            .distinct()
803	            .toList();
804	        detail.setProperty("errors", invalidFields);
805	        if (bindingResult.hasErrors()) {
806	            errors.addAllErrors(bindingResult);
807	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
808	                .map(fieldError -> {
809	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
810	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
811	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
812	                        fieldError.getField(),
813	                        defaultMessage,
814	                        rejectedValue);
815	                    return new ValidationMessageDto(message)
816	                        .putAdditionalProperty("field", fieldError.getField())
817	                        .putAdditionalProperty("rejectedValue", rejectedValue)
818	                        .putAdditionalProperty("defaultMessage", defaultMessage);
819	                })
820	                .toList();
821	            logger.debug("Validation error at {} {}: {}",
822	                request.getMethod(),
823	                request.getRequestURI(),
824	                bindingResult.getFieldErrors());
825	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
826	            return ResponseEntity.status(status).body(detail);
827	        }
828	        return ResponseEntity.status(status).body(detail);
829	    }
830	
831	    /**
832	     * Handles {@link RequiredFieldsMissingException} raised when a request omits or blanks
833	     * out mandatory fields. Returns a 400 Bad Request whose body carries an {@code errors}
834	     * array listing the name of each offending field.
835	     *
836	     * @param e The {@link RequiredFieldsMissingException} to be handled
837	     * @param request {@link HttpServletRequest} object referring to the current request.
838	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
839	     */
840	    @ExceptionHandler(RequiredFieldsMissingException.class)
841	    @ResponseBody
842	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
843	        HttpStatus status = HttpStatus.BAD_REQUEST;
844	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
845	        detail.setProperty("errors", e.getFields());
846	        logger.debug("Missing required fields at {} {}: {}",
847	            request.getMethod(),
848	            request.getRequestURI(),
849	            e.getFields());
850	        return ResponseEntity.status(status).body(detail);
851	    }
852	
853	    /**
854	     * Handles {@link DuplicateTelephoneException} raised when a create request supplies a
855	     * normalized telephone already used by another owner. Returns a 409 Conflict whose body
856	     * carries an {@code errors} array naming the {@code telephone} field.
857	     *
858	     * @param e The {@link DuplicateTelephoneException} to be handled
859	     * @param request {@link HttpServletRequest} object referring to the current request.
860	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
861	     */
862	    /**
863	     * Handles {@link InvalidEmailException} raised when a create or update request supplies an
864	     * {@code email} that is present but not a syntactically valid address. Returns a 400 Bad
865	     * Request whose body carries an {@code errors} array naming the {@code email} field.
866	     *
867	     * @param e The {@link InvalidEmailException} to be handled
868	     * @param request {@link HttpServletRequest} object referring to the current request.
869	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
870	     */
871	    @ExceptionHandler(InvalidEmailException.class)
872	    @ResponseBody
873	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
874	        HttpStatus status = HttpStatus.BAD_REQUEST;
875	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_EMAIL);
876	        detail.setProperty("errors", List.of("email"));
877	        logger.debug("Invalid email at {} {}: {}",
878	            request.getMethod(),
879	            request.getRequestURI(),
880	            e.getEmail());
881	        return ResponseEntity.status(status).body(detail);
882	    }
883	
884	    @ExceptionHandler(DuplicateTelephoneException.class)
885	    @ResponseBody
886	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
887	        HttpStatus status = HttpStatus.CONFLICT;
888	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
889	        detail.setProperty("errors", List.of("telephone"));
890	        logger.debug("Duplicate telephone at {} {}: {}",
891	            request.getMethod(),
892	            request.getRequestURI(),
893	            e.getTelephone());
894	        return ResponseEntity.status(status).body(detail);
895	    }
