package org.springframework.samples.petclinic.rest.controller;

/**
 * Raised when creating an owner whose last name and address match those of another owner
 * (compared case-insensitively with collapsed whitespace) and the request has not opted
 * in via {@code sharesHousehold}. Carries the offending last name and address so the
 * exception handler can report the conflict to the client as a 409 Conflict.
 */
public class DuplicateHouseholdException extends RuntimeException {

    private final String lastName;

    private final String address;

    public DuplicateHouseholdException(String lastName, String address) {
        super("An owner named '" + lastName + "' at address '" + address + "' already exists");
        this.lastName = lastName;
        this.address = address;
    }

    public String getLastName() {
        return this.lastName;
    }

    public String getAddress() {
        return this.address;
    }
}

